function bindControls(){
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;
renderControls()});
document.querySelectorAll('input[type=range][data-key]').forEach(el=>{el.oninput=()=>{let v=Number(el.value);
avatar[el.dataset.key]=v;
el.nextElementSibling.textContent=(Number(el.step)<1?v.toFixed(2):Math.round(v))+(el.dataset.key==='height'?' m':el.dataset.key==='walkSpeed'?'×':['posture','pace','curiosity','confidence','empathy','playfulness','smile','blinkRate','sway'].includes(el.dataset.key)?'%':'');
el.style.setProperty('--fill',`${(v-Number(el.min))/(Number(el.max)-Number(el.min))*100}%`);
drawCanvas()}});
document.querySelectorAll('select[data-key]').forEach(el=>el.onchange=()=>{avatar[el.dataset.key]=el.value;
drawCanvas()});
document.querySelectorAll('input[type=color][data-key]').forEach(el=>el.oninput=()=>{avatar[el.dataset.key]=el.value.toUpperCase();
drawCanvas();
renderControls()});
document.querySelectorAll('[data-color-key]').forEach(el=>el.onclick=()=>{avatar[el.dataset.colorKey]=el.dataset.color;
renderControls();
drawCanvas()});
document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));
document.querySelectorAll('.expression-btn').forEach(b=>b.onclick=()=>{avatar.expression=b.dataset.expression;
drawCanvas()});
document.querySelectorAll('.detail-chip,.accessory-chip,.voice-chip,.emotion-chip').forEach(b=>b.onclick=()=>{b.classList.toggle('active');
if(b.classList.contains('detail-chip')){
avatar.texture=b.dataset.detail;
drawCanvas()}});
document.querySelectorAll('.pose-select').forEach(b=>b.onclick=()=>setPose(b.dataset.pose));
document.querySelectorAll('.gesture').forEach(b=>b.onclick=()=>{avatar.gesture=b.dataset.gesture;
drawCanvas();
toast(`${b.dataset.gesture} gesture preview`) });
document.querySelectorAll('textarea[data-key]').forEach(el=>el.oninput=()=>avatar[el.dataset.key]=el.value);
const send=()=>{const input=document.querySelector('#command');
if(input)command(input.value)};
document.querySelector('#sendcommand')?.addEventListener('click',send);
document.querySelector('#command')?.addEventListener('keydown',e=>{if(e.key==='Enter')send()});
document.querySelector('#playanim')?.addEventListener('click',()=>{running=true;
toast('Animation preview playing')});
document.querySelector('#stopanim')?.addEventListener('click',()=>{running=false;
toast('Animation preview paused')});
document.querySelector('#loopanim')?.addEventListener('click',e=>{e.currentTarget.classList.toggle('active');
e.currentTarget.textContent=e.currentTarget.classList.contains('active')?'↻ Loop: on':'↻ Loop: off'})}
