function bindGlobal(){document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{activeSection=b.dataset.section;activeTab=(tabSets[activeSection]||tabSets.body)[0][0];renderControls();document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.section===activeSection));document.querySelectorAll('.mobile-tabs button').forEach(n=>n.classList.toggle('active',n.dataset.section===activeSection))});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('selected',x===b));avatar.rotate={front:0,side:90,back:180}[b.dataset.view];drawCanvas()});document.querySelectorAll('[data-pose]').forEach(b=>b.onclick=()=>setPose(b.dataset.pose));document.querySelector('#save').onclick=save;document.querySelector('#reset').onclick=()=>modalConfirm('Reset character?','This restores all details to the original Nova preset.',()=>{avatar={...defaults};render();toast('Character reset to original preset')});document.querySelector('#newchar').onclick=()=>{avatar={...defaults,name:'Nova '+Math.floor(Math.random()*90+10)};render();toast('New character created')};document.querySelector('#export').onclick=()=>download();document.querySelector('#import').onclick=()=>document.querySelector('#fileImport').click();if(!document.querySelector('#fileImport')){const f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.id='fileImport';f.hidden=true;document.body.append(f);f.onchange=importFile}document.querySelector('#more').onclick=()=>showModal(`<h2>Character options</h2><p>Manage your character profile. Customize any feature at any time—the live preview updates immediately.</p><div class="modal-actions"><button class="btn" id="mexport">Export JSON</button><button class="btn accent" id="mclose">Done</button></div>`);document.querySelector('#stage').onpointerdown=e=>{drag={x:e.clientX,rot:avatar.rotate};e.currentTarget.setPointerCapture(e.pointerId)};document.querySelector('#stage').onpointermove=e=>{if(!drag)return;avatar.rotate=drag.rot+(e.clientX-drag.x)*.65;drawCanvas()};document.querySelector('#stage').onpointerup=()=>drag=null;document.querySelector('#stage').onwheel=e=>{e.preventDefault();avatar.zoom=Math.max(70,Math.min(135,avatar.zoom+(e.deltaY<0?5:-5)));drawCanvas();document.querySelector('#zoomread').textContent=avatar.zoom+'%'};document.querySelector('#zoomin').onclick=()=>zoom(5);document.querySelector('#zoomout').onclick=()=>zoom(-5);document.querySelector('#zoomread').onclick=()=>{avatar.zoom=100;drawCanvas();document.querySelector('#zoomread').textContent='100%'};document.querySelectorAll('.pose-btn').forEach(b=>b.classList.toggle('active',b.dataset.pose.toLowerCase()===avatar.pose.toLowerCase()))}
function bindControls(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{activeTab=b.dataset.tab;renderControls()});document.querySelectorAll('input[type=range][data-key]').forEach(el=>{el.oninput=()=>{let v=Number(el.value);avatar[el.dataset.key]=v;el.nextElementSibling.textContent=(Number(el.step)<1?v.toFixed(2):Math.round(v))+(el.dataset.key==='height'?' m':el.dataset.key==='walkSpeed'?'×':['posture','pace','curiosity','confidence','empathy','playfulness','smile','blinkRate','sway'].includes(el.dataset.key)?'%':'');el.style.setProperty('--fill',`${(v-Number(el.min))/(Number(el.max)-Number(el.min))*100}%`);drawCanvas()}});document.querySelectorAll('select[data-key]').forEach(el=>el.onchange=()=>{avatar[el.dataset.key]=el.value;drawCanvas()});document.querySelectorAll('input[type=color][data-key]').forEach(el=>el.oninput=()=>{avatar[el.dataset.key]=el.value.toUpperCase();drawCanvas();renderControls()});document.querySelectorAll('[data-color-key]').forEach(el=>el.onclick=()=>{avatar[el.dataset.colorKey]=el.dataset.color;renderControls();drawCanvas()});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>applyPreset(b.dataset.preset));document.querySelectorAll('.expression-btn').forEach(b=>b.onclick=()=>{avatar.expression=b.dataset.expression;drawCanvas()});document.querySelectorAll('.detail-chip,.accessory-chip,.voice-chip,.emotion-chip').forEach(b=>b.onclick=()=>{b.classList.toggle('active');if(b.classList.contains('detail-chip')){avatar.texture=b.dataset.detail;drawCanvas()}});document.querySelectorAll('.pose-select').forEach(b=>b.onclick=()=>setPose(b.dataset.pose));document.querySelectorAll('.gesture').forEach(b=>b.onclick=()=>{avatar.gesture=b.dataset.gesture;drawCanvas();toast(`${b.dataset.gesture} gesture preview`) });document.querySelectorAll('textarea[data-key]').forEach(el=>el.oninput=()=>avatar[el.dataset.key]=el.value);const send=()=>{const input=document.querySelector('#command');if(input)command(input.value)};document.querySelector('#sendcommand')?.addEventListener('click',send);document.querySelector('#command')?.addEventListener('keydown',e=>{if(e.key==='Enter')send()});document.querySelector('#playanim')?.addEventListener('click',()=>{running=true;toast('Animation preview playing')});document.querySelector('#stopanim')?.addEventListener('click',()=>{running=false;toast('Animation preview paused')});document.querySelector('#loopanim')?.addEventListener('click',e=>{e.currentTarget.classList.toggle('active');e.currentTarget.textContent=e.currentTarget.classList.contains('active')?'↻ Loop: on':'↻ Loop: off'})}
